<script setup lang="ts">
import { ZoomIn, ZoomOut, Rotate, Flip, ChevronLeft, ChevronRight, Close } from './icons';
import { ref, watch } from 'vue';
import { useDialog } from './dialog';
import type { PreviewItem } from './image';
const props = defineProps<{ items: PreviewItem[]; index: number }>();
const emit = defineEmits<{ change: [index: number]; close: [] }>();
const layer = ref<HTMLElement | null>(null); const scale = ref(1), rotate = ref(0), flipX = ref(1), flipY = ref(1), x = ref(0), y = ref(0), loaded = ref(false), dragging = ref(false);
let drag: { x: number; y: number; ox: number; oy: number } | undefined;
function reset() { scale.value = 1; rotate.value = 0; flipX.value = flipY.value = 1; x.value = y.value = 0; }
watch(() => props.index, () => { reset(); loaded.value = false; });
useDialog(() => true, layer, () => emit('close'), () => true);
function zoom(delta: number) { scale.value = Math.max(0.25, Math.min(5, Number((scale.value + delta).toFixed(2)))); }
function go(direction: number) { emit('change', (props.index + direction + props.items.length) % props.items.length); }
function key(event: KeyboardEvent) { if (event.key === 'ArrowLeft') go(-1); else if (event.key === 'ArrowRight') go(1); else if (['+', '='].includes(event.key)) zoom(0.25); else if (event.key === '-') zoom(-0.25); else if (event.key === 'r') rotate.value += 90; else if (event.key === '0') reset(); else return; event.preventDefault(); }
function down(event: PointerEvent) { if (scale.value <= 1) return; event.preventDefault(); drag = { x: event.clientX, y: event.clientY, ox: x.value, oy: y.value }; dragging.value = true; (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId); }
function move(event: PointerEvent) { if (drag) { x.value = drag.ox + event.clientX - drag.x; y.value = drag.oy + event.clientY - drag.y; } }
function up() { drag = undefined; dragging.value = false; }
</script>
<template><Teleport to="body"><div ref="layer" class="at-image-preview" role="dialog" aria-modal="true" aria-label="图片预览" tabindex="-1" @keydown="key" @wheel.prevent="zoom($event.deltaY < 0 ? 0.1 : -0.1)"><div class="at-image-preview__backdrop" @click="emit('close')" /><header class="at-image-preview__header"><span v-if="items.length > 1" class="at-image-preview__counter">{{ index + 1 }} / {{ items.length }}</span><div class="at-image-preview__tools" role="toolbar" aria-label="图片操作"><button type="button" class="at-image-preview__tool" aria-label="放大" :disabled="scale >= 5" @click="zoom(0.25)"><ZoomIn /></button><button type="button" class="at-image-preview__tool" aria-label="缩小" :disabled="scale <= 0.25" @click="zoom(-0.25)"><ZoomOut /></button><button type="button" class="at-image-preview__tool" aria-label="向左旋转" @click="rotate -= 90"><Rotate /></button><button type="button" class="at-image-preview__tool" aria-label="向右旋转" @click="rotate += 90"><Rotate style="transform: scaleX(-1)" /></button><button type="button" class="at-image-preview__tool" aria-label="水平翻转" @click="flipX *= -1"><Flip /></button><button type="button" class="at-image-preview__tool" aria-label="垂直翻转" @click="flipY *= -1"><Flip style="transform: rotate(90deg)" /></button><span class="at-image-preview__scale" aria-live="polite">{{ Math.round(scale * 100) }}%</span><button type="button" class="at-image-preview__tool" aria-label="重置" @click="reset">1:1</button></div><button type="button" class="at-image-preview__close" aria-label="关闭预览" @click="emit('close')"><Close :size="22" /></button></header><template v-if="items.length > 1"><button type="button" class="at-image-preview__nav at-image-preview__nav--prev" aria-label="上一张" @click="go(-1)"><ChevronLeft :size="28" /></button><button type="button" class="at-image-preview__nav at-image-preview__nav--next" aria-label="下一张" @click="go(1)"><ChevronRight :size="28" /></button></template><img v-if="items[index]" :key="items[index].id" :src="items[index].previewSrc ?? items[index].src" alt="" :draggable="false" :class="['at-image-preview__img', { 'at-image-preview__img--dragging': dragging, 'at-image-preview__img--loaded': loaded, 'at-image-preview__img--zoomable': scale > 1 }]" :style="{ transform: `translate(${x}px, ${y}px) scale(${scale * flipX}, ${scale * flipY}) rotate(${rotate}deg)` }" @load="loaded = true" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @click.stop></div></Teleport></template>
